'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const list = (d,k) => Array.isArray(d) ? d : (d?.[k] || []);
const base = document.querySelector('meta[name="ai-memory-base-path"]')?.content || '';
const fmt = n => Number(n || 0).toLocaleString('pt-BR');
const events = n => `${fmt(n)} ${Number(n)===1?'evento':'eventos'}`;
const date = value => value ? new Date(value).toLocaleString('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}) : 'Sem atividade ainda';
const names = {overview:'Sua memória de trabalho.',pages:'Memórias do projeto.',sessions:'Cada sessão, seu contexto.',handoffs:'Continue de onde parou.',review:'O que não deve continuar.',cleanup:'Mantenha só o que importa.',search:'Encontre o que ficou salvo.'};
const subtitles = {overview:'Decisões, contexto e próximos passos. Tudo no mesmo lugar.',pages:'Consulte o conhecimento que suas IAs registraram.',sessions:'Veja as conversas registradas e os eventos de cada sessão.',handoffs:'O contexto preparado para a próxima sessão de trabalho.',review:'Páginas vazias, paradas ou em conflito. Nada é apagado nesta tela.',cleanup:'Revise o que ficou salvo e remova o que não ajuda mais as suas IAs.',search:'Busca no conteúdo das memórias, respeitando o projeto selecionado.'};
const kinds = {decision:'Decisão',session:'Sessão',rule:'Regra',note:'Nota',fact:'Fato',concept:'Conceito',procedure:'Procedimento',gotcha:'Aprendizado',slot:'Contexto',open:'Pendente',accepted:'Aceito',expired:'Expirado'};
const ages = [[0,'Qualquer data'],[7,'Mais de 7 dias'],[30,'Mais de 30 dias'],[90,'Mais de 90 dias']];
const SEARCH_HINT = 'Busque uma decisão, um problema ou uma ideia';
const icon = {trash:'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4.5 6.5h15M9.5 6.5V4.8c0-.7.6-1.3 1.3-1.3h2.4c.7 0 1.3.6 1.3 1.3v1.7M6.5 6.5l.8 12.2c.1 1 .9 1.8 1.9 1.8h5.6c1 0 1.8-.8 1.9-1.8l.8-12.2M10.2 10.5v6M13.8 10.5v6"/></svg>',check:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6.5 12.5l3.5 3.5 7.5-8"/></svg>',tick:'<svg class="icon tick" viewBox="0 0 24 24" aria-hidden="true"><path d="M6.5 12.5l3.5 3.5 7.5-8"/></svg>',clock:'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/></svg>',chevron:'<svg class="icon chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 10l5 5 5-5"/></svg>',save:'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 4.5h10c.6 0 1 .4 1 1v14l-6-3.5-6 3.5v-14c0-.6.4-1 1-1z"/></svg>'};
const UNDO_MS = 6000;
const reduced = matchMedia('(prefers-reduced-motion: reduce)');
const freshFilters = () => ({kind:'all',age:0,text:''});
let projects=[], scope=null, view='overview', epoch=0, detailEpoch=0, actions=[], busy=false, logos={}, switchIndex=0, lastCount=null, reading=null;
// Estado da biblioteca: linhas carregadas, filtros, seleção e a exclusão que ainda pode ser desfeita.
let library=[], filters=freshFilters(), selecting=false, preset=null, pending=null, inflight=[];
const picked=new Set(), hiddenKeys=new Set(), entries=new Map();
const keyOf = (p,item) => `${p.workspace_name}/${p.project_name}::${item.path}`;
const pathFor = p => '/workspaces/'+encodeURIComponent(p.workspace_name)+'/projects/'+encodeURIComponent(p.project_name);
async function api(path,params={}){const url=new URL(base+'/api/v1'+path,location.origin);Object.entries(params).forEach(([k,v])=>url.searchParams.set(k,v));const r=await fetch(url,{credentials:'include',cache:'no-store',headers:{Accept:'application/json'}});if(!r.ok)throw new Error(r.status===401?'Sua sessão expirou ou o servidor exige autenticação.':`O servidor retornou ${r.status}. Tente atualizar.`);return r.json();}
// A API /api/v1 é somente leitura; alterações usam as mesmas ferramentas MCP que as IAs usam.
const mcpInit = body => ({method:'POST',credentials:'include',cache:'no-store',headers:{'Content-Type':'application/json',Accept:'application/json, text/event-stream'},body:JSON.stringify({jsonrpc:'2.0',id:Date.now(),method:'tools/call',params:body})});
async function mcp(name,args){const r=await fetch(base+'/mcp',mcpInit({name,arguments:args}));if(!r.ok)throw new Error(r.status===401?'O servidor exige autenticação para alterar memórias.':`O servidor recusou a alteração (${r.status}).`);let text=await r.text();if((r.headers.get('content-type')||'').includes('event-stream'))text=text.split('\n').filter(l=>l.startsWith('data:')).map(l=>l.slice(5)).pop()||'{}';const d=JSON.parse(text);if(d.error)throw new Error(d.error.message||'Não foi possível concluir a alteração.');const out=(d.result?.content||[]).map(c=>c.text||'').join('');if(d.result?.isError)throw new Error(out||'Não foi possível concluir a alteração.');try{return JSON.parse(out);}catch{return out;}}
function action(fn){const id=actions.push(fn)-1;return `data-action="${id}"`;}
function empty(symbol,title,body,extra='',cls=''){return `<div class="empty ${cls}"><span class="empty-symbol" aria-hidden="true">${symbol}</span><h3>${esc(title)}</h3><p>${esc(body)}</p>${extra}</div>`;}
function skeleton(){return `<div class="skeleton" aria-hidden="true">${'<div class="sk-row"><span></span><span></span></div>'.repeat(4)}</div><span class="visually-hidden">Carregando…</span>`;}
function card(title,body,link=''){return `<section class="card"><div class="card-header"><h2>${esc(title)}</h2>${link}</div>${body}</section>`;}
function link(label,target){return `<a href="#${target}" class="text-link">${label} ↗</a>`;}
function selected(){return scope===null?projects:[projects[scope]].filter(Boolean);}
function setScope(i){scope=i;$('#search').value='';syncClear();filters=freshFilters();selecting=false;picked.clear();closeSwitcher(true);sidebar();render();}
const sameProject = (a,b) => a.workspace_name===b.workspace_name&&a.project_name===b.project_name;
const scopeArgs = p => ({workspace:p.workspace_name,project:p.project_name});
const linesOf = value => String(value||'').split('\n').map(s=>s.trim()).filter(Boolean);
const scopedProject = () => scope===null?null:projects[scope]||null;
const slugPath = title => {const s=title.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,48);return `notes/${s||'nota'}.md`;};
const consolLabels = {pending:'Resumo na fila',running:'Resumindo',completed:'Resumo salvo',failed:'Resumo falhou',superseded:'Resumo substituído'};
const findingKinds = {contradiction:'Contradição',stale:'Desatualizada',duplicate:'Duplicada',empty:'Vazia',other:'Atenção'};
function consolPill(s){const c=s.consolidation;if(!c?.state)return '';const cls=c.state==='failed'?' warn':c.state==='running'?' live':'';return `<span class="pill${cls}">${esc(consolLabels[c.state]||c.state)}</span>`;}
// Contagem exibida = valor do servidor menos as exclusões pendentes ou ainda em envio.
function countFor(p){return Math.max(0,(p.page_count||0)-[...(pending?.items||[]),...inflight].filter(e=>sameProject(e.p,p)).length);}
const totalFor = ps => ps.reduce((n,p)=>n+countFor(p),0);
// ---------- Logos e seletor de projetos ----------
// As logos vêm de logos/manifest.json, gerado por tools/sync-logos.py; sem logo, um monograma colorido.
const logosReady = fetch('logos/manifest.json',{cache:'no-store'}).then(r=>r.ok?r.json():{}).then(m=>{logos=m||{};}).catch(()=>{});
const hue = s => [...s].reduce((h,c)=>(h*31+c.charCodeAt(0))%360,7);
const initials = name => (name.split(/[-_\s.]+/).filter(Boolean).length>1?name.split(/[-_\s.]+/).filter(Boolean).slice(0,2).map(w=>w[0]):[...name.replace(/[^A-Za-z0-9]/g,'')].slice(0,2)).join('').toUpperCase()||'?';
function logo(p){const src=logos[`${p.workspace_name}/${p.project_name}`],mono=esc(initials(p.project_name)),style=`--h:${hue(p.project_name)}`;return src?`<img class="plogo" src="${esc(src)}" alt="" loading="lazy" data-mono="${mono}" style="${style}">`:`<span class="plogo mono" style="${style}" aria-hidden="true">${mono}</span>`;}
function logoStack(ps){const pick=[...ps.filter(p=>logos[`${p.workspace_name}/${p.project_name}`]),...ps].filter((p,i,a)=>a.indexOf(p)===i).slice(0,3);return `<span class="plogo-stack">${pick.map(logo).join('')||'<span class="plogo mono">∅</span>'}</span>`;}
function highlight(text,q){if(!q)return esc(text);const i=text.toLowerCase().indexOf(q);return i<0?esc(text):esc(text.slice(0,i))+'<mark>'+esc(text.slice(i,i+q.length))+'</mark>'+esc(text.slice(i+q.length));}
function projectItems(){const q=$('#project-filter').value.trim().toLowerCase();return [...(q?[]:[{p:null,i:null}]),...projects.map((p,i)=>({p,i})).filter(({p})=>!q||`${p.project_name} ${p.workspace_name}`.toLowerCase().includes(q))];}
function paintProjects(){const q=$('#project-filter').value.trim().toLowerCase(),items=projectItems();switchIndex=Math.min(switchIndex,Math.max(0,items.length-1));$('#project-list').innerHTML=items.length?items.map(({p,i},k)=>{const n=p?countFor(p):totalFor(projects);return `<button type="button" role="option" id="project-opt-${k}" tabindex="-1" class="switcher-item${p?'':' all'}${k===switchIndex?' focused':''}${n?'':' zero'}" aria-selected="${i===scope}" data-scope="${i===null?'all':i}">${p?logo(p):logoStack(projects)}<span class="si-main"><strong>${p?highlight(p.project_name,q):'Todos os projetos'}</strong><small>${p?(p.last_updated?'Atualizado '+date(p.last_updated):'Sem memórias ainda'):`Visão combinada de ${projects.length} projetos`}</small></span><span class="count">${fmt(n)}</span>${icon.tick}</button>`;}).join(''):`<p class="switcher-empty">Nenhum projeto com “${esc(q)}”.</p>`;$('#project-filter').setAttribute('aria-activedescendant',items.length?`project-opt-${switchIndex}`:'');$('#project-total').textContent=`${projects.length} ${projects.length===1?'projeto':'projetos'}`;}
function moveProject(delta){const all=[...$('#project-list').querySelectorAll('.switcher-item')];if(!all.length)return;switchIndex=(switchIndex+delta+all.length)%all.length;all.forEach((b,k)=>b.classList.toggle('focused',k===switchIndex));$('#project-filter').setAttribute('aria-activedescendant',`project-opt-${switchIndex}`);all[switchIndex].scrollIntoView({block:'nearest'});}
function openSwitcher(){const w=$('#switcher');if(w.classList.contains('open'))return;$('#project-filter').value='';switchIndex=scope===null?0:scope+1;paintProjects();w.classList.add('open');$('#project-button').setAttribute('aria-expanded','true');$('#project-list .focused')?.scrollIntoView({block:'nearest'});setTimeout(()=>$('#project-filter').focus(),30);}
function closeSwitcher(focus){const w=$('#switcher');if(!w?.classList.contains('open'))return;w.classList.remove('open');$('#project-button').setAttribute('aria-expanded','false');if(focus)$('#project-button').focus();}
function recentProjects(){return projects.map((p,i)=>({p,i})).filter(x=>x.p.last_updated).sort((a,b)=>String(b.p.last_updated).localeCompare(String(a.p.last_updated))).slice(0,5);}
function sidebar(){const cur=scope===null?null:projects[scope],n=cur?countFor(cur):totalFor(projects),b=$('#project-button');b.innerHTML=`${cur?logo(cur):logoStack(projects)}<strong>${esc(cur?cur.project_name:'Todos os projetos')}</strong><span class="count">${fmt(n)}</span>${icon.chevron}`;b.title=cur?`${cur.workspace_name}/${cur.project_name}`:'Todos os projetos';b.setAttribute('aria-label',`Projeto: ${cur?cur.project_name:'todos os projetos'}, ${fmt(n)} ${n===1?'memória':'memórias'}. Trocar de projeto`);const forKey=cur?cur.project_name:'*';if(lastCount!==null&&lastCount!==n&&b.dataset.for===forKey)b.querySelector('.count').classList.add('bump');lastCount=n;b.dataset.for=forKey;const rec=recentProjects();$('#recent-projects').innerHTML=rec.length?`<span class="recent-label">Recentes</span>${rec.map(({p,i})=>`<button type="button" class="recent-item${i===scope?' on':''}" data-scope="${i}" title="${esc(p.project_name)} · ${fmt(countFor(p))} ${countFor(p)===1?'memória':'memórias'}" aria-label="Abrir ${esc(p.project_name)}">${logo(p)}</button>`).join('')}`:'';if($('#switcher').classList.contains('open'))paintProjects();const m=$('[data-metric="pages"]');if(m){const t=totalFor(selected());m.dataset.count=t;m.textContent=fmt(t);}}
function pageRow(p,item){const key=keyOf(p,item),on=picked.has(key),title=item.title||item.path;entries.set(key,{p,item,key});return `<div class="row-wrap${on?' picked':''}" data-key="${esc(key)}"><span class="check" aria-hidden="true">${icon.check}</span><button class="row" ${action(()=>readPage(p,item))}${selecting?` aria-pressed="${on}"`:''}><span class="row-icon" aria-hidden="true">${logo(p)}</span><span class="row-main"><strong>${esc(title)}</strong><small>${esc(p.project_name)} · ${esc(item.path)}</small>${item.snippet?`<p>${esc(item.snippet).replaceAll('&lt;mark&gt;','<mark>').replaceAll('&lt;/mark&gt;','</mark>')}</p>`:''}</span><span class="pill">${esc(kinds[item.kind]||item.kind||'Memória')}</span></button><button type="button" class="row-action" data-delete="${esc(key)}" aria-label="Excluir ${esc(title)}" title="Excluir memória">${icon.trash}</button></div>`;}
function metric(label,n,note,id=''){return `<div class="metric"><div class="metric-label">${label}</div><div class="metric-number"${id?` data-metric="${id}"`:''} data-count="${Number(n)||0}">${fmt(n)}</div><div class="metric-note">${note}</div></div>`;}
async function overview(ps){const data=await Promise.all(ps.map(async p=>({p,...await api(pathFor(p)+'/overview',{limit:8})})));const count=k=>data.reduce((n,d)=>n+(d.briefing?.counts?.[k]||0),0);const pending=data.reduce((n,d)=>n+(d.briefing?.pending_handoff_count||0),0);const recent=data.flatMap(d=>(d.briefing?.recent_pages||[]).map(item=>({p:d.p,item}))).filter(r=>!hiddenKeys.has(keyOf(r.p,r.item))).sort((a,b)=>String(b.item.updated_at).localeCompare(String(a.item.updated_at))).slice(0,5);const handoffs=data.filter(d=>d.handoff).sort((a,b)=>String(b.handoff.at).localeCompare(String(a.handoff.at)));return `<div class="metrics">${metric('Memórias salvas',totalFor(ps),'Conhecimento disponível','pages')}${metric('Sessões registradas',count('sessions'),'Histórico de trabalho')}${metric('Eventos capturados',count('observations'),'Prompts e ações das IAs')}${metric('Handoffs pendentes',pending,'Contexto para a próxima IA')}</div><div class="columns">${card('Memórias recentes',recent.length?recent.map(r=>pageRow(r.p,r.item)).join(''):empty('▤','Seu contexto começa aqui','Assim que uma sessão gerar memórias, suas decisões e aprendizados aparecerão neste espaço.'),link('Ver memórias','pages'))}${card('Pronto para continuar',handoffs.length?handoffRow(handoffs[0].p,handoffs[0].handoff):empty('⇄','Nenhum handoff pendente','Ao trocar de IA, peça para salvar um handoff com o que foi feito e os próximos passos.','','handoff-empty'),link('Ver handoffs','handoffs'))}</div><section class="project-section"><div class="section-title"><h2>${scope===null?'Seus projetos':'Projeto selecionado'}</h2><span>${ps.length} ${ps.length===1?'projeto':'projetos'} · contextos separados</span></div><div class="project-cards">${ps.map(p=>`<button class="project-card" ${action(()=>{setScope(projects.indexOf(p));location.hash='pages';})}><span class="folder" aria-hidden="true">${logo(p)}</span><strong>${esc(p.project_name)}</strong><small>${fmt(p.page_count)} memórias · ${esc(p.workspace_name)}</small></button>`).join('')}</div></section><div class="guide"><span aria-hidden="true">↳</span><div><strong>Uma conversa termina. Seu contexto continua.</strong><p>Peça à IA: “Salve um handoff”. Na próxima sessão, pergunte: “Onde paramos?”.</p></div><a href="#sessions" class="text-link">Ver sessões ↗</a></div>`;}
function handoffRow(p,h){const open=h.state==='open'&&h.id;return `<div class="row-wrap"><button class="row" ${action(()=>readHandoff(p,h))}><span class="row-icon" aria-hidden="true">${logo(p)}</span><span class="row-main"><strong>${esc(p.project_name)}</strong><small>${esc(h.agent||'IA')} · ${date(h.at)}</small><p>${esc((h.summary||'Contexto disponível para consulta.').slice(0,200))}</p></span><span class="pill">${esc(kinds[h.state]||h.state||'Pendente')}</span></button>${open?`<button type="button" class="row-action" ${action(()=>discardHandoff(p,h))} aria-label="Descartar handoff de ${esc(p.project_name)}" title="Descartar handoff">${icon.trash}</button>`:''}</div>`;}

// ---------- Biblioteca com filtros e seleção ----------
async function loadLibrary(ps,query){const rows=(await Promise.all(ps.map(async p=>{const d=await api(query?'/search':pathFor(p)+'/pages',query?{q:query,workspace:p.workspace_name,project:p.project_name,limit:100}:{});return list(d,query?'hits':'pages').map(item=>({p,item,key:keyOf(p,item)}));}))).flat();if(!query)rows.sort((a,b)=>String(b.item.updated_at).localeCompare(String(a.item.updated_at)));return rows;}
function libraryView(title){const age=ages.find(([v])=>v===filters.age)||ages[0];return `<section class="card library-card"><div class="card-header"><h2>${esc(title)}</h2>${view==='pages'?'<button type="button" class="text-link" id="new-page">Nova página</button>':''}<span class="muted" id="library-count"></span></div><div class="library-tools"><div id="kind-tabs" class="tabs on-card" role="radiogroup" aria-label="Tipo de memória"></div><div class="tools-end"><div class="menu-wrap" id="age-wrap"><button type="button" class="pill-button${filters.age?' on':''}" id="age-button" aria-haspopup="menu" aria-expanded="false" aria-controls="age-menu">${icon.clock}<span id="age-label">${age[1]}</span>${icon.chevron}</button><div class="menu" id="age-menu" role="menu" aria-label="Idade da memória">${ages.map(([v,t])=>`<button type="button" role="menuitemradio" aria-checked="${v===filters.age}" data-filter="age" data-value="${v}">${icon.tick}<span>${t}</span></button>`).join('')}</div></div><button type="button" class="pill-button" id="toggle-select" aria-pressed="${selecting}">${selecting?'Concluir':'Selecionar'}</button></div></div><div id="library-list" class="library-list"></div></section>`;}
function kindTabs(){const live=library.filter(r=>!hiddenKeys.has(r.key)),counts={};live.forEach(r=>{const k=r.item.kind||'note';counts[k]=(counts[k]||0)+1;});const opts=[['all','Todas',live.length],...Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([k,n])=>[k,kinds[k]||k,n])];if(filters.kind!=='all'&&!counts[filters.kind])opts.push([filters.kind,kinds[filters.kind]||filters.kind,0]);return opts.map(([v,t,n])=>`<button type="button" role="radio" aria-checked="${v===filters.kind}" data-filter="kind" data-value="${esc(v)}"${n?'':' class="zero"'}><span>${esc(t)}</span><span class="count">${fmt(n)}</span></button>`).join('')+'<span class="tabs-thumb" aria-hidden="true"></span>';}
function closeMenu(){const w=$('#age-wrap');if(!w?.classList.contains('open'))return;w.classList.remove('open');$('#age-button').setAttribute('aria-expanded','false');}
function toggleMenu(){const w=$('#age-wrap'),open=!w.classList.contains('open');w.classList.toggle('open',open);$('#age-button').setAttribute('aria-expanded',open);if(open)w.querySelector('[aria-checked="true"]')?.focus();}
function setAge(value){filters.age=value;$('#age-menu')?.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-checked',Number(b.dataset.value)===value));const b=$('#age-button');if(b){b.classList.toggle('on',!!value);$('#age-label').textContent=(ages.find(([v])=>v===value)||ages[0])[1];}}
function visibleRows(){const text=view==='pages'?filters.text.trim().toLowerCase():'',cut=filters.age?Date.now()-filters.age*864e5:0;return library.filter(r=>!hiddenKeys.has(r.key)&&(filters.kind==='all'||(r.item.kind||'note')===filters.kind)&&(!cut||new Date(r.item.updated_at).getTime()<cut)&&(!text||`${r.item.title||''} ${r.item.path} ${r.p.project_name}`.toLowerCase().includes(text)));}
function libraryEmpty(){if(library.some(r=>!hiddenKeys.has(r.key)))return empty('▤','Nada com esses filtros','Ajuste o tipo, a idade ou o texto da busca para ver mais memórias.','<button type="button" class="button secondary small" id="clear-filters">Limpar filtros</button>');return view==='search'?empty('⌕','Nenhum resultado encontrado','Tente outro termo ou selecione todos os projetos.'):empty('▤','Ainda não há memórias','As páginas salvas pelas IAs aparecerão aqui.');}
function paintLibrary(rebuild=true){const box=$('#library-list');if(!box)return;if(rebuild)$('#kind-tabs').innerHTML=kindTabs();const rows=visibleRows(),keys=new Set(rows.map(r=>r.key));picked.forEach(k=>{if(!keys.has(k))picked.delete(k);});box.innerHTML=rows.length?rows.map(r=>pageRow(r.p,r.item)).join(''):libraryEmpty();const total=library.filter(r=>!hiddenKeys.has(r.key)).length;$('#library-count').textContent=rows.length===total?`${fmt(total)} ${total===1?'item':'itens'}${view==='search'?' · até 100 por projeto':''}`:`${fmt(rows.length)} de ${fmt(total)}`;updateSelection();}
function updateSelection(){const list=$('#library-list'),on=selecting&&!!list,bar=$('#selection-bar');document.body.classList.toggle('selecting',on);document.body.classList.toggle('bar-open',on);document.querySelectorAll('#library-list .row-wrap').forEach(w=>{const is=picked.has(w.dataset.key),b=w.querySelector('.row');w.classList.toggle('picked',is);if(on)b.setAttribute('aria-pressed',is);else b.removeAttribute('aria-pressed');});const t=$('#toggle-select');if(t){t.textContent=selecting?'Concluir':'Selecionar';t.setAttribute('aria-pressed',selecting);}const n=picked.size,visible=list?list.querySelectorAll('.row-wrap').length:0;bar.classList.toggle('show',on);bar.inert=!on;$('#selection-count').textContent=n?`${fmt(n)} ${n===1?'selecionada':'selecionadas'}`:'Nenhuma selecionada';$('#select-all').textContent=n&&n===visible?'Desmarcar tudo':'Selecionar tudo';$('#select-all').disabled=!visible;$('#delete-selected').disabled=!n;}
function togglePick(key){if(picked.has(key))picked.delete(key);else picked.add(key);updateSelection();}
function selectAll(){const keys=[...document.querySelectorAll('#library-list .row-wrap')].map(w=>w.dataset.key);if(keys.length&&keys.every(k=>picked.has(k)))picked.clear();else keys.forEach(k=>picked.add(k));updateSelection();}
function endSelect(){selecting=false;picked.clear();updateSelection();}

// ---------- Exclusão com janela para desfazer ----------
const rowFor = key => [...document.querySelectorAll('.row-wrap[data-key]')].find(w=>w.dataset.key===key);
function collapse(el){if(!el)return Promise.resolve();if(reduced.matches||!el.animate){el.remove();return Promise.resolve();}const h=el.offsetHeight;el.style.overflow='hidden';return el.animate([{height:h+'px',opacity:1,transform:'none'},{height:'0px',opacity:0,transform:'translateX(-28px)'}],{duration:420,easing:'cubic-bezier(.28,.11,.32,1)'}).finished.then(()=>el.remove(),()=>el.remove());}
function afterChange(){if($('#library-list'))paintLibrary();else render();}
async function deletePages(keys){const items=keys.map(k=>entries.get(k)).filter(Boolean);if(!items.length)return;if(items.length>1){const ok=await confirmBox({title:`Excluir ${fmt(items.length)} memórias?`,body:'Elas deixam de aparecer nas buscas e para as suas IAs. Você ainda terá alguns segundos para desfazer.',items:items.map(e=>e.item.title||e.item.path),ok:'Excluir'});if(!ok)return;selecting=false;}if(pending)commit(pending);items.forEach(e=>{hiddenKeys.add(e.key);picked.delete(e.key);});const batch={items};pending=batch;batch.timer=setTimeout(()=>commit(batch),UNDO_MS);batch.dismiss=toast(items.length===1?'Memória excluída.':`${fmt(items.length)} memórias excluídas.`,{duration:UNDO_MS,undo:()=>{if(pending!==batch)return;clearTimeout(batch.timer);pending=null;items.forEach(e=>hiddenKeys.delete(e.key));sidebar();afterChange();}});updateSelection();sidebar();await Promise.all(items.map(e=>collapse(rowFor(e.key))));if(pending===batch&&$('#library-list'))paintLibrary();}
async function commit(batch){if(batch.done)return;batch.done=true;clearTimeout(batch.timer);inflight.push(...batch.items);if(pending===batch)pending=null;batch.dismiss?.();const res=await Promise.allSettled(batch.items.map(e=>mcp('memory_delete_page',{path:e.item.path,workspace:e.p.workspace_name,project:e.p.project_name})));const gone=new Set(batch.items.filter((e,i)=>res[i].status==='fulfilled').map(e=>e.key));library=library.filter(r=>!gone.has(r.key));batch.items.forEach(e=>{const p=gone.has(e.key)&&projects.find(x=>sameProject(x,e.p));if(p)p.page_count=Math.max(0,(p.page_count||0)-1);});inflight=inflight.filter(e=>!batch.items.includes(e));sidebar();const failed=batch.items.filter((e,i)=>res[i].status==='rejected');if(failed.length){failed.forEach(e=>hiddenKeys.delete(e.key));toast(`Não foi possível excluir ${failed.length===1?'1 memória':fmt(failed.length)+' memórias'}. ${res.find(r=>r.status==='rejected').reason.message}`,{tone:'error',duration:8000});afterChange();}syncProjects().catch(()=>{});}
// Se a aba fechar durante a janela de desfazer, a exclusão confirmada ainda é enviada.
addEventListener('pagehide',()=>{if(!pending)return;const b=pending;pending=null;b.done=true;b.items.forEach(e=>fetch(base+'/mcp',{...mcpInit({name:'memory_delete_page',arguments:{path:e.item.path,workspace:e.p.workspace_name,project:e.p.project_name}}),keepalive:true}).catch(()=>{}));});
async function discardHandoff(p,h){if(!await confirmBox({title:'Descartar este handoff?',body:'A próxima sessão não vai receber este contexto. Ele continua no histórico como expirado.',ok:'Descartar'}))return;try{await mcp('memory_handoff_cancel',{handoff_id:h.id,workspace:p.workspace_name,project:p.project_name});toast('Handoff descartado.');render();}catch(e){toast(e.message,{tone:'error',duration:8000});}}

// ---------- Limpeza ----------
const sweepStats=[['expired','Vencidas, apagadas'],['evicted','Pouco usadas, arquivadas'],['compacted','Compactadas'],['merged','Mescladas'],['hard_deleted','Arquivadas antigas, apagadas'],['observations','Eventos antigos']];
function cleanupView(ps){const count=f=>library.filter(r=>!hiddenKeys.has(r.key)&&f(r)).length,old=Date.now()-30*864e5;const tiles=[['Memórias de sessão','Resumos gerados automaticamente ao fim de cada conversa.',count(r=>r.item.kind==='session'),{kind:'session',age:0}],['Mais de 30 dias','Memórias que não foram atualizadas no último mês.',count(r=>new Date(r.item.updated_at).getTime()<old),{kind:'all',age:30}],['Todas as memórias','Revise a biblioteca inteira e escolha o que sai.',count(()=>true),{kind:'all',age:0}]];return `<div class="cleanup"><section class="card sweep-card"><div class="sweep-copy"><span class="eyebrow">Faxina automática</span><h2>Deixe a memória em ordem.</h2><p>Memórias vencidas são apagadas, memórias de sessão pouco consultadas são arquivadas e arquivos antigos são removidos de vez. Primeiro você vê a prévia. Nada muda antes da sua confirmação.</p></div><div id="sweep-result" aria-live="polite"></div><div class="sweep-actions"><button type="button" class="button" id="sweep-preview">Analisar ${ps.length===1?esc(ps[0].project_name):'todos os projetos'}</button></div></section><section class="review"><div class="section-title"><h2>Revisão manual.</h2><span>Escolha um ponto de partida e selecione o que remover.</span></div><div class="review-grid">${tiles.map(([t,d,n,f])=>`<button type="button" class="review-tile" ${action(()=>{preset={...f,text:''};location.hash='pages';})}><span class="review-number" data-count="${n}">${fmt(n)}</span><span><strong>${t}</strong><small>${d}</small></span><span class="go">Revisar e selecionar ↗</span></button>`).join('')}</div></section></div>`;}
function allClear(title,body){return `<div class="all-clear"><svg viewBox="0 0 52 52" aria-hidden="true"><circle cx="26" cy="26" r="24"/><path d="M15 27l7 7 15-16"/></svg><div><strong>${esc(title)}</strong><span>${esc(body)}</span></div></div>`;}
function paintSweep(results,dry){const size=v=>Array.isArray(v)?v.length:Number(v)||0;const totals=sweepStats.map(([k,label])=>[label,results.reduce((n,{r})=>n+size(k==='observations'?(dry?r.observations_prunable:r.observations_pruned):r[k]),0)]);const total=totals.reduce((n,[,v])=>n+v,0);const paths=results.flatMap(({p,r})=>['expired','evicted','compacted','merged'].flatMap(k=>(Array.isArray(r[k])?r[k]:[]).map(x=>`${p.project_name} · ${typeof x==='string'?x:(x.path||x.title||JSON.stringify(x))}`)));const again='<button type="button" class="button secondary" id="sweep-preview">Analisar de novo</button>';if(dry&&!total){$('#sweep-result').innerHTML=allClear('Nada para limpar agora.','Sua memória já está em ordem.');$('.sweep-actions').innerHTML=again;return;}$('#sweep-result').innerHTML=(dry?'':allClear('Faxina concluída.',`${fmt(total)} ${total===1?'item tratado':'itens tratados'}.`))+`<div class="stats">${totals.map(([l,v])=>`<div class="stat${v?'':' zero'}"><b>${fmt(v)}</b><span>${l}</span></div>`).join('')}</div>${paths.length?`<ul class="sweep-list">${paths.slice(0,8).map(x=>`<li>${esc(x)}</li>`).join('')}${paths.length>8?`<li class="muted">e mais ${fmt(paths.length-8)}</li>`:''}</ul>`:''}`;$('.sweep-actions').innerHTML=dry?`<button type="button" class="button danger" id="sweep-run">Executar faxina</button>${again}`:again;}
async function sweep(dry){const ps=selected(),box=$('#sweep-result'),bar=$('.sweep-actions');if(!box)return;if(!dry&&!await confirmBox({title:'Executar a faxina agora?',body:'As memórias listadas na prévia serão arquivadas ou apagadas conforme as regras de retenção.',ok:'Executar faxina'}))return;bar.querySelectorAll('button').forEach(b=>b.disabled=true);box.innerHTML=`<div class="sweep-loading"><span class="spinner" aria-hidden="true"></span>${dry?'Analisando…':'Limpando…'}</div>`;try{const results=await Promise.all(ps.map(async p=>({p,r:await mcp('memory_forget_sweep',{dry_run:dry,workspace:p.workspace_name,project:p.project_name})})));if(!box.isConnected)return;paintSweep(results,dry);if(!dry){toast('Faxina concluída.');syncProjects().catch(()=>{});}}catch(e){if(box.isConnected)box.innerHTML=`<p class="form-error">${esc(e.message)}</p>`;}finally{if(bar.isConnected)bar.querySelectorAll('button').forEach(b=>b.disabled=false);}}

// ---------- Salvar sessão ----------
function sessionChoice(r,i){return `<label class="choice"><input type="radio" name="save-pick" value="${i}"${i?'':' checked'}><span class="choice-mark" aria-hidden="true"></span><span class="choice-body"><strong>${esc(r.s.agent_kind||'IA')} · ${esc(r.p.project_name)}</strong><small>${r.s.ended_at?'Encerrada':'<b class="live-dot">Ativa</b>'} · desde ${date(r.s.started_at)} · ${events(r.s.observation_count)}</small></span></label>`;}
async function saveSession(target){const d=$('#save-dialog'),body=$('#save-body'),bar=$('#save-actions');body.innerHTML='<div class="sweep-loading"><span class="spinner" aria-hidden="true"></span>Procurando sessões…</div>';bar.innerHTML='';if(!d.open)d.showModal();let rows;try{rows=target?[target]:(await Promise.all(selected().map(async p=>list(await api(pathFor(p)+'/sessions',{include_open:true,limit:20}),'sessions').map(s=>({p,s}))))).flat().sort((a,b)=>String(b.s.started_at).localeCompare(String(a.s.started_at)));}catch(e){body.innerHTML=`<p class="form-error">${esc(e.message)}</p>`;bar.innerHTML='<button type="button" class="button secondary" data-close>Fechar</button>';return;}const open=rows.filter(r=>!r.s.ended_at),shown=(open.length?open:rows).slice(0,5);if(!shown.length){body.innerHTML='<p class="sheet-note">Nenhuma sessão registrada neste projeto ainda.</p>';bar.innerHTML='<button type="button" class="button secondary" data-close>Fechar</button>';return;}body.innerHTML=`${open.length||target?'':'<p class="sheet-note">Nenhuma sessão ativa agora. Estas são as mais recentes:</p>'}<div class="choices" role="radiogroup" aria-label="Sessão">${shown.map(sessionChoice).join('')}</div><label class="switch-row"><span><strong>Extrair decisões e aprendizados</strong><small>Além do resumo, cria páginas separadas para conceitos, decisões e armadilhas.</small></span><input type="checkbox" role="switch" id="save-multi"><span class="switch" aria-hidden="true"></span></label>`;bar.innerHTML='<button type="button" class="button secondary" data-close>Cancelar</button><button type="button" class="button" id="save-run">Salvar na memória</button>';$('#save-run').onclick=()=>runSave(shown[Number(d.querySelector('[name="save-pick"]:checked').value)],$('#save-multi').checked);}
async function runSave({p,s},multi){const d=$('#save-dialog');$('#save-body').innerHTML=`<div class="sweep-loading"><span class="spinner" aria-hidden="true"></span><span>Resumindo ${events(s.observation_count)} com o LLM configurado. Pode levar até um minuto; você pode fechar esta janela.</span></div>`;$('#save-actions').innerHTML='';try{const out=await mcp('memory_consolidate',{session_id:s.session_id,multi_page:multi,workspace:p.workspace_name,project:p.project_name});const path=out?.path||out?.pages?.[0]?.path||`sessions/${s.session_id}.md`,title=out?.new_title||out?.title||'Resumo da sessão';syncProjects().catch(()=>{});if(view!=='cleanup')render();if(!d.open){toast('Sessão salva na memória.');return;}$('#save-body').innerHTML=allClear('Sessão salva na memória.',`${title} · ${path}`);$('#save-actions').innerHTML='<button type="button" class="button secondary" data-close>Fechar</button><button type="button" class="button" id="save-open">Abrir memória</button>';$('#save-open').onclick=()=>{closeDialog(d);readPage(p,{path,title});};}catch(e){if(!d.open){toast(e.message,{tone:'error',duration:8000});return;}$('#save-body').innerHTML=`<p class="form-error">${esc(e.message)}</p>`;$('#save-actions').innerHTML='<button type="button" class="button secondary" data-close>Fechar</button>';}}

// ---------- Diálogos e avisos ----------
function closeDialog(d,value=''){if(!d.open||d.classList.contains('closing'))return;if(reduced.matches){d.close(value);return;}d.classList.add('closing');setTimeout(()=>{d.classList.remove('closing');d.close(value);},220);}
function confirmBox({title,body,items=[],ok='Excluir'}){return new Promise(resolve=>{const d=$('#confirm');$('#confirm-title').textContent=title;$('#confirm-body').textContent=body;$('#confirm-list').innerHTML=items.slice(0,5).map(t=>`<li>${esc(t)}</li>`).join('')+(items.length>5?`<li class="muted">e mais ${fmt(items.length-5)}</li>`:'');$('#confirm-ok').textContent=ok;d.returnValue='';d.addEventListener('close',()=>resolve(d.returnValue==='ok'),{once:true});d.showModal();$('#confirm-cancel').focus();});}
function toast(message,{undo,tone,duration=3600}={}){const box=$('#toasts'),t=document.createElement('div');t.className='toast'+(tone?' '+tone:'');t.setAttribute('role',tone==='error'?'alert':'status');t.innerHTML=`<span class="toast-text"></span>${undo?'<button type="button" class="toast-undo">Desfazer</button>':''}<span class="toast-timer" style="--ms:${duration}ms"></span>`;t.querySelector('.toast-text').textContent=message;const close=()=>{if(t.dataset.gone)return;t.dataset.gone='1';t.classList.add('leaving');setTimeout(()=>t.remove(),reduced.matches?0:260);};const timer=setTimeout(close,duration);if(undo)t.querySelector('.toast-undo').onclick=()=>{clearTimeout(timer);undo();close();};box.append(t);while(box.children.length>3)box.firstElementChild.remove();return close;}

function projectField(){const cur=scopedProject();if(cur)return `<input type="hidden" name="project" value="${projects.indexOf(cur)}"><p class="sheet-note">Projeto <strong>${esc(cur.project_name)}</strong>.</p>`;if(!projects.length)return '<p class="sheet-note">Nenhum projeto registrado ainda.</p>';return `<label class="field project-field"><span>Projeto</span><select name="project">${projects.map((p,i)=>`<option value="${i}">${esc(p.project_name)}</option>`).join('')}</select></label>`;}
function projectFromForm(form){const value=form.project?.value;if(value==null||value==='')return scopedProject();return projects[Number(value)]||null;}
function openCompose(kind){const d=$('#compose'),body=$('#compose-body');$('#compose-error').hidden=true;d.dataset.kind=kind;if(kind==='handoff'){$('#compose-label').textContent='HANDOFF';$('#compose-title').textContent='Deixe o contexto para a próxima IA.';$('#compose-lead').textContent='A próxima sessão neste projeto recebe este resumo, os passos e as perguntas.';body.innerHTML=projectField()+'<label class="field"><span>Onde paramos</span><textarea name="summary" required rows="4" placeholder="O que ficou decidido e o que ainda está aberto."></textarea></label><label class="field"><span>Próximos passos</span><textarea name="next_steps" rows="3" placeholder="Um passo por linha"></textarea></label><label class="field"><span>Perguntas em aberto</span><textarea name="open_questions" rows="3" placeholder="Uma pergunta por linha"></textarea></label><label class="field"><span>Arquivos</span><textarea name="files" rows="2" placeholder="Um caminho por linha"></textarea></label>';}else{$('#compose-label').textContent='NOVA PÁGINA';$('#compose-title').textContent='Guarde um fato que deve durar.';$('#compose-lead').textContent='A página entra na wiki e passa a aparecer para as IAs deste projeto.';body.innerHTML=projectField()+'<label class="switch-row"><span><strong>Vale para todos os projetos</strong><small>A página entra no escopo global. Não fica presa a um repositório.</small></span><input type="checkbox" role="switch" id="page-global" name="global"><span class="switch" aria-hidden="true"></span></label><label class="field"><span>Título</span><input name="title" required placeholder="Usamos pnpm neste projeto" autocomplete="off"></label><label class="field"><span>Caminho</span><input name="path" placeholder="notes/pnpm.md" autocomplete="off" spellcheck="false"></label><label class="field"><span>Tipo</span><select name="kind"><option value="note">Nota</option><option value="decision">Decisão</option><option value="rule">Regra</option><option value="fact">Fato</option><option value="procedure">Procedimento</option><option value="gotcha">Aprendizado</option></select></label><label class="field"><span>Conteúdo</span><textarea name="body" rows="5" placeholder="O fato, com o contexto necessário para a próxima IA."></textarea></label>';$('#page-global').addEventListener('change',()=>{const on=$('#page-global').checked;body.querySelectorAll('.project-field,.sheet-note').forEach(el=>{el.hidden=on;});});}$('#compose-actions').innerHTML=`<button type="button" class="button secondary" data-close>Cancelar</button><button type="submit" class="button" id="compose-submit">${kind==='handoff'?'Deixar handoff':'Salvar página'}</button>`;if(!d.open)d.showModal();body.querySelector('textarea,input:not([type="hidden"]):not([type="checkbox"])')?.focus();}
function composeError(message){const box=$('#compose-error');box.textContent=message;box.hidden=false;}
async function submitHandoff(form){const p=projectFromForm(form);if(!p)throw new Error('Escolha um projeto.');const summary=form.summary.value.trim();if(!summary)throw new Error('Escreva onde a sessão parou.');await mcp('memory_handoff_begin',{summary,next_steps:linesOf(form.next_steps.value),open_questions:linesOf(form.open_questions.value),files_touched:linesOf(form.files.value),...scopeArgs(p)});toast('Handoff deixado para a próxima sessão.');}
async function submitPage(form){const title=form.title.value.trim();let body=form.body.value.trim();if(!title)throw new Error('Dê um título à página.');if(!body.startsWith('#'))body=`# ${title}\n\n${body||title}`;let path=(form.path.value.trim()||slugPath(title)).replace(/^\/+/,'');if(!path.endsWith('.md'))path+='.md';const args={path,body,kind:form.kind.value||null};if(form.global?.checked)args.scope='global';else{const p=projectFromForm(form);if(!p)throw new Error('Escolha um projeto.');Object.assign(args,scopeArgs(p));}await mcp('memory_write_page',args);toast('Página salva na memória.');}
function reviewShell(){const p=scopedProject();if(!p)return empty('◎','Escolha um projeto','A revisão olha um projeto por vez. Abra o seletor e escolha qual memória auditar.');return `<section class="card sweep-card"><div class="sweep-copy"><span class="eyebrow">${esc(p.project_name)}</span><h2>O que não deve continuar.</h2><p>A análise rápida procura páginas vazias, duplicadas ou paradas. A análise com o modelo também procura contradições. Nada é apagado. Marcar uma memória como errada na leitura entra na próxima passagem.</p></div><div id="review-result" aria-live="polite"></div><div class="sweep-actions"><button type="button" class="button secondary" id="review-fast">Análise rápida</button><button type="button" class="button" id="review-llm">Analisar com o modelo</button></div></section>`;}
function paintReview(report){const findings=Array.isArray(report)?report:(report?.findings||[]);const box=$('#review-result');if(!box)return;if(!findings.length){box.innerHTML=allClear('Nada a revisar agora.','Esta passagem não encontrou páginas vazias, duplicadas ou em conflito.');return;}const p=scopedProject();box.innerHTML=`<div class="finding-list">${findings.map(f=>{const pages=(f.pages||[]).map(path=>`<button type="button" class="text-link" data-open-page="${esc(path)}">${esc(path.split('/').pop())}</button>`).join('');return `<article class="finding"><span class="pill">${esc(findingKinds[f.kind]||f.kind||'Nota')}</span><strong>${esc(f.message||'Achado sem descrição.')}</strong>${f.detail?`<p>${esc(f.detail)}</p>`:''}${pages?`<div class="finding-pages">${pages}</div>`:''}</article>`;}).join('')}</div>`;void p;}
async function runReview(withModel){const p=scopedProject();const box=$('#review-result'),bar=$('.sweep-actions');if(!p||!box)return;bar?.querySelectorAll('button').forEach(b=>b.disabled=true);box.innerHTML=`<div class="sweep-loading"><span class="spinner" aria-hidden="true"></span>${withModel?'Analisando com o modelo…':'Analisando…'}</div>`;try{const report=await mcp('memory_lint',{dry_run:true,no_llm:!withModel,...scopeArgs(p)});if(box.isConnected)paintReview(report);}catch(e){if(box.isConnected)box.innerHTML=`<p class="form-error">${esc(e.message)}</p>`;}finally{if(bar?.isConnected)bar.querySelectorAll('button').forEach(b=>b.disabled=false);}}
function feedbackBar(){return `<div class="feedback"><span>Esta memória ajudou?</span><div class="feedback-actions"><button type="button" class="pill-button" data-signal="helpful">Útil</button><button type="button" class="pill-button" data-signal="not_helpful">Não ajudou</button><button type="button" class="pill-button" data-signal="stale">Desatualizada</button><button type="button" class="pill-button" data-signal="wrong">Errada</button></div><form class="feedback-why" id="feedback-why" hidden><input name="reason" type="text" placeholder="O que mudou, em uma linha" maxlength="500" autocomplete="off"><button type="submit" class="button small">Registrar</button></form></div>`;}
async function sendFeedback(signal,reason){if(!reading)return;await mcp('memory_feedback',{path:reading.path,signal,reason:reason||null,...scopeArgs(reading.p)});const labels={helpful:'Marcada como útil.',not_helpful:'Marcada como pouco útil.',stale:'Marcada como desatualizada. Entra na próxima revisão.',wrong:'Marcada como errada. Entra na próxima revisão.'};toast(labels[signal]||'Avaliação registrada.');}
const RELEASE_URL='https://api.github.com/repos/akitaonrails/ai-memory/releases/latest';
let release={state:'idle',local:'',latest:'',at:0};
const verParts=value=>String(value||'').replace(/^v/,'').split('.').map(n=>parseInt(n,10)||0);
function cmpVer(a,b){const pa=verParts(a),pb=verParts(b),n=Math.max(pa.length,pb.length);for(let i=0;i<n;i++){const d=(pa[i]||0)-(pb[i]||0);if(d)return d;}return 0;}
async function serverVersion(){const r=await fetch(base+'/mcp',{method:'POST',credentials:'include',cache:'no-store',headers:{'Content-Type':'application/json',Accept:'application/json, text/event-stream'},body:JSON.stringify({jsonrpc:'2.0',id:Date.now(),method:'initialize',params:{protocolVersion:'2025-03-26',capabilities:{},clientInfo:{name:'imemory',version:'1'}}})});if(!r.ok)throw new Error('sem versão');let text=await r.text();if((r.headers.get('content-type')||'').includes('event-stream'))text=text.split('\n').filter(l=>l.startsWith('data:')).map(l=>l.slice(5)).pop()||'{}';const version=JSON.parse(text).result?.serverInfo?.version;if(!version)throw new Error('sem versão');return String(version).replace(/^v/,'');}
async function upstreamVersion(){const r=await fetch(RELEASE_URL,{cache:'no-store',headers:{Accept:'application/vnd.github+json'}});if(!r.ok)throw new Error('github');const tag=(await r.json()).tag_name;if(!tag)throw new Error('github');return String(tag).replace(/^v/,'');}
function releaseMessage(){if(release.state==='behind')return `Este Mac está no ai-memory ${release.local}. A versão publicada é ${release.latest}.`;if(release.state==='current')return `Este Mac está no ai-memory ${release.local}, a mesma versão publicada.`;if(release.state==='ahead')return `Este Mac está no ai-memory ${release.local}, à frente da publicação ${release.latest}.`;if(release.local)return `Não foi possível comparar com o GitHub. O servidor local está na ${release.local}.`;return 'Não foi possível ler a versão do servidor.';}
function paintConnection(online){const el=$('#connection');const behind=release.state==='behind'||(release.state==='checking'&&release.local&&release.latest&&cmpVer(release.local,release.latest)<0);el.classList.toggle('online',!!online);el.classList.toggle('update',!!online&&!!behind);if(!online){el.textContent='Falha na consulta';el.title='O servidor local não respondeu. Clique para tentar de novo.';return;}if(release.state==='checking'&&release.local){el.textContent=release.latest&&cmpVer(release.local,release.latest)<0?`Atualização ${release.latest}`:`Servidor conectado · ${release.local}`;el.title='Conferindo a versão publicada…';return;}if(release.state==='behind'){el.textContent=`Atualização ${release.latest}`;el.title=`Este Mac está no ai-memory ${release.local}. A versão publicada por Fabio Akita é ${release.latest}. Clique para conferir de novo.`;return;}if(release.local&&(release.state==='current'||release.state==='ahead'||release.state==='unknown')){el.textContent=`Servidor conectado · ${release.local}`;el.title=release.state==='ahead'?`Este Mac está no ai-memory ${release.local}, à frente da publicação ${release.latest}. Clique para conferir de novo.`:release.state==='unknown'?'Não foi possível comparar com o GitHub. Clique para tentar de novo.':`Este Mac está no ai-memory ${release.local}, igual à versão publicada. Clique para conferir de novo.`;return;}el.textContent='Servidor conectado';el.title='Comparando com a versão publicada do ai-memory…';}
async function checkRelease(force){if(release.state==='checking')return;if(!force&&release.at&&Date.now()-release.at<600000&&release.state!=='idle'&&release.state!=='unknown'){paintConnection(true);return;}release.state='checking';paintConnection(true);try{release.local=await serverVersion();}catch{release.local='';release.latest='';release.state='unknown';release.at=Date.now();paintConnection(true);return;}try{release.latest=await upstreamVersion();const delta=cmpVer(release.local,release.latest);release.state=delta<0?'behind':delta>0?'ahead':'current';}catch{release.state='unknown';}release.at=Date.now();paintConnection(true);}
async function onConnection(){if(!$('#connection').classList.contains('online')){refresh();return;}await checkRelease(true);toast(releaseMessage(),{duration:6400});}
async function render(){const token=++epoch;let next=location.hash.slice(1)||'overview';if(!names[next])next='overview';if(next!==view){picked.clear();if(preset){filters=preset;selecting=true;preset=null;}else{filters=freshFilters();selecting=false;}}view=next;document.body.dataset.view=view;$('#search').placeholder=view==='pages'?'Filtre esta lista. Enter busca no conteúdo.':SEARCH_HINT;if(view==='pages')filters.text=$('#search').value.trim();actions=[];$('#heading').textContent=names[view];$('#subtitle').textContent=subtitles[view];document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#view').setAttribute('aria-busy','true');$('#notice').hidden=true;$('#view').innerHTML=skeleton();updateSelection();try{let html;const ps=selected();if(view==='overview')html=await overview(ps);else if(view==='pages'||view==='search'){const query=$('#search').value.trim();if(view==='search'&&!query){html=empty('⌕','O que você quer encontrar?','Digite algo no campo de busca acima.');}else{const rows=await loadLibrary(ps,view==='search'?query:null);if(token!==epoch)return;library=rows;html=libraryView(view==='search'?`Resultados para “${query}”`:'Biblioteca de memórias');}}else if(view==='cleanup'){const rows=await loadLibrary(ps,null);if(token!==epoch)return;library=rows;html=cleanupView(ps);}else if(view==='sessions'){const rows=(await Promise.all(ps.map(async p=>list(await api(pathFor(p)+'/sessions',{include_open:true,limit:100}),'sessions').map(item=>({p,item}))))).flat().sort((a,b)=>String(b.item.started_at).localeCompare(String(a.item.started_at)));html=card('Sessões de trabalho',rows.length?rows.map(({p,item:s})=>`<div class="row-wrap"><button class="row" ${action(()=>readSession(p,s))}><span class="row-icon" aria-hidden="true">${logo(p)}</span><span class="row-main"><strong>${esc(s.agent_kind||'IA')} · ${esc(p.project_name)}</strong><small>${date(s.started_at)} · ${events(s.observation_count)}</small></span>${consolPill(s)}<span class="pill${s.ended_at?'':' live'}">${s.ended_at?'Encerrada':'Ativa'}</span></button><button type="button" class="row-action save" ${action(()=>saveSession({p,s}))} aria-label="${s.consolidation?.state==='failed'?'Resumir de novo a sessão de ':'Salvar sessão de '}${esc(s.agent_kind||'IA')}" title="${s.consolidation?.state==='failed'?'Resumir de novo':'Salvar na memória'}">${icon.save}</button></div>`).join(''):empty('◷','Nenhuma sessão registrada','Depois de recarregar as integrações, as sessões capturadas poderão ser consultadas aqui.'),'<span class="muted">Até 100 recentes por projeto</span>');}else if(view==='review'){html=reviewShell();}else{const rows=(await Promise.all(ps.map(async p=>list(await api(pathFor(p)+'/handoffs',{limit:100}),'handoffs').map(item=>({p,item}))))).flat().sort((a,b)=>String(b.item.at).localeCompare(String(a.item.at)));html=card('Histórico de handoffs',rows.length?rows.map(r=>handoffRow(r.p,r.item)).join(''):empty('⇄','Nenhum handoff registrado','Deixe um contexto para a próxima IA, ou peça isso no chat.'),'<button type="button" class="text-link" id="new-handoff">Deixar contexto</button>');}if(token!==epoch)return;$('#view').innerHTML=html;paintLibrary();updateSelection();paintConnection(true);checkRelease(false);$('#updated').textContent='Atualizado às '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});}catch(e){if(token!==epoch)return;showError(e);$('#view').innerHTML=empty('!','Não foi possível carregar','Verifique se o servidor está disponível e clique em atualizar.','','error-empty');}finally{if(token===epoch)$('#view').setAttribute('aria-busy','false');}}
function showError(e){$('#notice').textContent=e.message;$('#notice').hidden=false;paintConnection(false);}
function modal(title,label,meta,body){$('#reader-title').textContent=title;$('#reader-label').textContent=label;$('#reader-meta').textContent=meta;$('#reader-body').innerHTML=body;$('#reader-actions').innerHTML='';if(!$('#reader').open){$('#reader-scroll').scrollTop=0;$('#reader-top').classList.remove('shadow');$('#reader').showModal();}}
function readerAction(label,run){const b=document.createElement('button');b.type='button';b.className='text-danger';b.innerHTML=`${icon.trash}<span>${esc(label)}</span>`;b.onclick=()=>{closeDialog($('#reader'));run();};$('#reader-actions').append(b);}
function readerButton(label,run){const b=document.createElement('button');b.type='button';b.className='button secondary small';b.textContent=label;b.onclick=()=>{closeDialog($('#reader'));run();};$('#reader-actions').append(b);}
function observationPayload(body){const text=String(body||''),i=text.indexOf('\n---\n');return i<0?text:text.slice(i+5);}
function filePathsIn(body){return [...String(body||'').matchAll(/filePath"\s*:\s*"([^"]+)"/g)].map(m=>m[1]);}
function orphanName(payload){const text=payload.trim();if(/^<svg[\s>]/i.test(text))return 'favicon.svg';if(/^<!doctype html/i.test(text)||/^<html[\s>]/i.test(text))return 'index.html';if(/^\/\*/.test(text)&&text.includes('{'))return 'styles.css';const script=text.match(/\b([\w.-]+\.mjs)\b/);if(script&&text.startsWith('//'))return script[1];if(/^#\s+\S/.test(text))return 'README.md';return '';}
function boilerPrompt(o){const t=`${o.title||''}\n${String(o.body||'').slice(0,280)}`;return /browser automation|<browser_instruction>/i.test(t)||/continue from where you left off/i.test(t);}
function sessionFacts(observations){const files=new Map(),orphans=new Map();let tools=0,labeled=0,real=0,images=0;for(const o of observations){const title=o.title||'';if(o.kind==='user-prompt'&&!boilerPrompt(o))real++;if(o.kind==='pre-tool-use'||o.kind==='post-tool-use'){tools++;if(title.startsWith('tool '))labeled++;}if(o.kind!=='post-tool-use')continue;const payload=observationPayload(o.body);if(/"type"\s*:\s*"image"/.test(payload)){images++;continue;}const paths=filePathsIn(o.body);if(paths.length){for(const path of paths){const prev=files.get(path);if(!prev||String(o.body||'').length>String(prev.body||'').length)files.set(path,o);}}else{const name=orphanName(payload);if(name){const prev=orphans.get(name);if(!prev||String(o.body||'').length>String(prev.body||'').length)orphans.set(name,o);}}}for(const [name,o] of orphans){if(![...files.keys()].some(p=>p===name||p.endsWith('/'+name)))files.set(name,o);}return {files:[...files.entries()],shallow:tools>=8&&labeled/tools>0.55&&real===0,images};}
function displayBody(o){const body=String(o.body||'');return /"type"\s*:\s*"image"/.test(body)?'Leitura de imagem. O conteúdo binário foi omitido nesta vista.':body;}
function sessionBrief(facts){if(!facts.shallow&&!facts.files.length)return '';const warn=facts.shallow?`<div class="session-callout"><strong>O resumo automático não descreve esta sessão.</strong><p>${facts.files.length?'O pedido original não ficou registrado. Os arquivos abaixo são o que dá para reconstruir.':'A maior parte dos eventos ficou só com um identificador, sem comando nem resultado.'}</p></div>`:'';const rows=facts.files.map(([path,o])=>{const name=path.split('/').pop(),dir=path.includes('/')?path.split('/').slice(0,-1).slice(-2).join('/'):'gravado sem caminho no evento';return `<details class="file-hit"><summary><span class="file-name">${esc(name)}</span><span class="muted">${esc(dir)}</span></summary><pre>${esc(observationPayload(o.body).slice(0,700))}</pre></details>`;}).join('');const extra=facts.images?`<p class="muted session-aside">${fmt(facts.images)} ${facts.images===1?'leitura de imagem ficou':'leituras de imagem ficaram'} de fora desta lista.</p>`:'';return warn+(rows?`<section class="session-files"><h3>Arquivos gravados</h3><div class="file-rows">${rows}</div>${extra}</section>`:'');}
function inline(s){return esc(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');}
// Render a small, safe Markdown subset. Raw HTML and URLs are never executed.
function markdown(s){let code=false,ul=false,out=[];for(const line of String(s||'').split('\n')){if(/^```/.test(line)){if(ul){out.push('</ul>');ul=false;}out.push(code?'</code></pre>':'<pre><code>');code=!code;continue;}if(code){out.push(esc(line)+'\n');continue;}if(/^[-*] /.test(line)){if(!ul){out.push('<ul>');ul=true;}out.push('<li>'+inline(line.slice(2))+'</li>');continue;}if(ul){out.push('</ul>');ul=false;}const h=line.match(/^(#{1,6}) (.+)$/);out.push(h?`<h${Math.min(h[1].length+1,6)}>${inline(h[2])}</h${Math.min(h[1].length+1,6)}>`:line.startsWith('> ')?'<blockquote>'+inline(line.slice(2))+'</blockquote>':line?'<p>'+inline(line)+'</p>':'');}if(ul)out.push('</ul>');if(code)out.push('</code></pre>');return out.join('');}
async function readPage(p,item){const token=++detailEpoch;modal(item.title||item.path,'MEMÓRIA',p.project_name,'<p>Carregando…</p>');try{const page=await api(pathFor(p)+'/pages/'+item.path.split('/').map(encodeURIComponent).join('/'));if(token!==detailEpoch)return;const text=page.body_markdown??page.body??'',fm=page.frontmatter||{},tags=(fm.tags||[]).map(t=>`<span class="pill">${esc(t)}</span>`).join('');reading={p,path:page.path||item.path,title:page.title||item.title||item.path};modal(page.title||page.path,kinds[page.kind]||'MEMÓRIA',p.project_name+' · '+date(page.updated_at),(fm.summary?`<p class="reader-summary">${esc(fm.summary)}</p>`:'')+(tags?`<div class="reader-tags">${tags}</div>`:'')+(text.trim()?markdown(text):'<p class="muted">Esta página não tem conteúdo.</p>')+`<details><summary>Ver Markdown original</summary><pre>${esc(text)}</pre></details>`+feedbackBar());const key=keyOf(p,{path:reading.path});entries.set(key,{p,item:{...item,path:reading.path},key});readerAction('Excluir memória',()=>deletePages([key]));}catch(e){if(token===detailEpoch)$('#reader-body').textContent=e.message;}}
function readHandoff(p,h){detailEpoch++;const sections=[['Próximos passos',h.next_steps],['Questões em aberto',h.open_questions],['Arquivos envolvidos',h.files_touched]];modal('Contexto para continuar','HANDOFF',p.project_name+' · '+(h.agent||'IA')+' · '+date(h.at),h.redacted?'<p>O servidor restringiu o conteúdo deste handoff à identidade que o criou.</p>':markdown(h.summary||'Sem resumo disponível.')+sections.filter(([,v])=>v?.length).map(([title,items])=>`<h3>${title}</h3><ul>${items.map(x=>`<li>${esc(typeof x==='string'?x:JSON.stringify(x))}</li>`).join('')}</ul>`).join(''));if(h.state==='open'&&h.id)readerAction('Descartar handoff',()=>discardHandoff(p,h));}
async function readSession(p,s){const token=++detailEpoch;modal('Eventos da sessão','SESSÃO',p.project_name+' · '+(s.agent_kind||'IA'),'<p>Carregando…</p>');const all=[];let offset=0,total=0;try{do{const d=await api(pathFor(p)+'/sessions/'+encodeURIComponent(s.session_id)+'/observations',{limit:80,offset,body_max_chars:2400});if(token!==detailEpoch)return;total=d.total||0;const batch=d.observations||[];all.push(...batch);offset+=batch.length;if(!batch.length)break;}while(offset<total&&offset<400);}catch(e){if(token===detailEpoch)$('#reader-body').textContent=e.message;return;}if(token!==detailEpoch)return;const facts=sessionFacts(all);const events=all.map(o=>`<details><summary>${esc(o.title||o.kind)} <span class="muted">${date(o.created_at)}</span></summary><pre>${esc(displayBody(o))}</pre></details>`).join('');const more=offset<total?`<p class="muted session-aside">Mostrando ${fmt(offset)} de ${fmt(total)} eventos.</p>`:'';$('#reader-body').innerHTML=sessionBrief(facts)+`<details class="event-dump"><summary>Todos os eventos <span class="muted">${fmt(total)}</span></summary>${events}${more}</details>`;readerButton('Resumir de novo',()=>saveSession({p,s}));}
async function syncProjects(){const old=scope===null?null:projects[scope];projects=list(await api('/projects'),'projects').sort((a,b)=>a.project_name.localeCompare(b.project_name));scope=old?projects.findIndex(p=>p.project_name===old.project_name&&p.workspace_name===old.workspace_name):null;if(scope===-1)scope=null;sidebar();}
async function refresh(){if(busy)return;busy=true;$('#refresh').disabled=true;try{await logosReady;await syncProjects();await render();}catch(e){showError(e);$('#view').setAttribute('aria-busy','false');$('#view').innerHTML=empty('!','Servidor indisponível','Não foi possível consultar a biblioteca. Clique em atualizar para tentar novamente.');}finally{busy=false;$('#refresh').disabled=false;}}
function syncClear(){$('#search-clear').classList.toggle('show',!!$('#search').value);}
document.addEventListener('click',e=>{const anchor=e.target.closest('a[href^="#"]');if(anchor&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey){e.preventDefault();const hash=anchor.getAttribute('href');if(hash==='#content')$('#content').focus();else location.hash=hash;}
  const wrap=selecting&&e.target.closest('#library-list .row-wrap');if(wrap){togglePick(wrap.dataset.key);return;}
  const del=e.target.closest('[data-delete]');if(del){deletePages([del.dataset.delete]);return;}
  if(!e.target.closest('#age-wrap'))closeMenu();
  if(!e.target.closest('#switcher'))closeSwitcher();
  if(e.target.closest('#project-button')){$('#switcher').classList.contains('open')?closeSwitcher(true):openSwitcher();return;}
  const closer=e.target.closest('[data-close]');if(closer){closeDialog(closer.closest('dialog'));return;}
  const seg=e.target.closest('[data-filter]');if(seg){if(seg.dataset.filter==='age'){setAge(Number(seg.dataset.value));closeMenu();$('#age-button').focus();}else{filters.kind=seg.dataset.value;seg.parentNode.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-checked',b===seg));}paintLibrary(false);return;}
  const id=e.target.closest('button[id]')?.id;
  if(id==='toggle-select'){selecting=!selecting;if(!selecting)picked.clear();updateSelection();return;}
  if(id==='age-button'){toggleMenu();return;}
  if(id==='clear-filters'){filters=freshFilters();setAge(0);$('#search').value='';syncClear();paintLibrary();return;}
  if(id==='sweep-preview'){sweep(true);return;}
  if(id==='sweep-run'){sweep(false);return;}
  if(id==='new-handoff'){openCompose('handoff');return;}
  if(id==='new-page'){openCompose('page');return;}
  if(id==='review-fast'){runReview(false);return;}
  if(id==='review-llm'){runReview(true);return;}
  if(id==='connection'){onConnection();return;}
  const signal=e.target.closest('[data-signal]');if(signal&&reading){const kind=signal.dataset.signal;if(kind==='stale'||kind==='wrong'){const form=$('#feedback-why');if(form){form.hidden=false;form.dataset.signal=kind;form.reason.focus();}}else sendFeedback(kind).catch(err=>toast(err.message,{tone:'error',duration:8000}));return;}
  const pageBtn=e.target.closest('[data-open-page]');if(pageBtn&&scopedProject()){readPage(scopedProject(),{path:pageBtn.dataset.openPage,title:pageBtn.dataset.openPage});return;}
  const a=e.target.closest('[data-action]');if(a)actions[Number(a.dataset.action)]?.();const p=e.target.closest('[data-scope]');if(p)setScope(p.dataset.scope==='all'?null:Number(p.dataset.scope));});
