$('#project-list').addEventListener('mousemove',e=>{const b=e.target.closest('.switcher-item');if(!b)return;const all=[...$('#project-list').querySelectorAll('.switcher-item')],k=all.indexOf(b);if(k!==switchIndex){switchIndex=k;all.forEach((x,j)=>x.classList.toggle('focused',j===k));}});
