document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#search').focus();}if((e.metaKey||e.ctrlKey)&&e.key==='j'){e.preventDefault();openSwitcher();}if(e.key==='Escape'&&$('#age-wrap.open')){closeMenu();$('#age-button').focus();return;}if(e.key==='Escape'&&selecting&&!document.querySelector('dialog[open]'))endSelect();const item=e.target.closest?.('#age-menu [role="menuitemradio"]');if(item&&(e.key==='ArrowDown'||e.key==='ArrowUp')){e.preventDefault();const all=[...$('#age-menu').children],i=all.indexOf(item);all[(i+(e.key==='ArrowDown'?1:all.length-1))%all.length].focus();}});
